    for v in q['potential']:upd('potential',v)
  elif r['op']=='step' and r['status']=='advanced':
   for k in ['load','z','dual','pressure']:
    for v in r[k]:upd(k,v)
   upd('ceiling',r['ceiling'])
  elif r['op']=='audit':
   for row in r['flow']:
    for v in row:upd('flow',v)
   for row in r['worker_load']:
    for v in row:upd('worker_load',v)
   for k in ['load','z','dual']:
    for v in r[k]:upd(k,v)
print(mx)
